import { describe, expect, it } from "vitest";
import { loadConfig } from "@code-health/cli-kit/config";
import { treeFromTexts } from "@code-health/parse/source-tree";
import { complexityConfig, readSettings } from "../src/config.ts";
import { measureTree } from "../src/measure.ts";

const tree = treeFromTexts({
  "a/gen.pb.go": "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage a\n\nfunc Big() int {\n\tif true {\n\t\treturn 1\n\t}\n\treturn 2\n}\n",
  "a/hand.go": "package a\n\nfunc Hand() int {\n\treturn 1\n}\n",
});

describe("a generated Go file", () => {
  it.each(["structural", "lexical"] as const)("is not measured on the %s layer", async (layer) => {
    const settings = readSettings(loadConfig("/nonexistent", complexityConfig));
    const measurement = await measureTree(tree, { settings, layer });
    expect(measurement.files.map((file) => file.path)).toEqual(["a/hand.go"]);
    expect(measurement.skippedFiles.excluded).toBe(1);
  });
});
